def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0) or 0

    # Network referral rule: self_employed with requested_limit > 6000 must
    # be queued for review instead of issued, regardless of partner decision.
    # A decline stays a decline.
    self_employed_high = (
        app.get("employment") == "self_employed"
        and app.get("requested_limit", 0) > 6000
    )

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    if outcome == "approved":
        if self_employed_high:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}

    # manual_review (and any other non-decision) -> queue_review, never decline
    return {"action": "queue_review", "limit": 0}
